}

{
  "items": [
    {
      "need": "Para dados públicos, verificar a aprovação para uso público e utilizar canal de negócios aprovado.",
      "use": "category",
      "condition": "Quando os dados enviados forem classificados como Public.",
      "scope_link": {
        "question_quote": "antes de enviar dados a um fornecedor externo",
        "explanation": "A regra define a condição e o canal mínimo para o compartilhamento externo de dados públicos."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-9b0d28fc0e3086af15def6c5a4d43fa93965cbbaa1b1a4ddf2803d4fb420ec35",
          "quote": "Public | May be shared when approved for public use. | Approved business channel."
        }
      ]
    },
    {
      "need": "Para dados internos, compartilhar somente por necessidade legítima de negócio e utilizar canal gerenciado pela empresa.",
      "use": "category",
      "condition": "Quando os dados enviados forem classificados como Internal.",
      "scope_link": {
        "question_quote": "antes de enviar dados a um fornecedor externo",
        "explanation": "A regra estabelece a finalidade permitida e o canal mínimo para enviar dados internos ao fornecedor."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-9b0d28fc0e3086af15def6c5a4d43fa93965cbbaa1b1a4ddf2803d4fb420ec35",
          "quote": "Internal | Share only for legitimate business need. | Corporate-managed channel."
        }
      ]
    },
    {
      "need": "Para dados confidenciais, exigir destinatário autorizado e finalidade de negócio aprovada, utilizar transferência segura aprovada ou plataforma controlada apropriada à classificação e limitar o acesso aos destinatários pretendidos; o uso de e-mail corporativo, por si só, não aprova uma transferência não aprovada.",
      "use": "category",
      "condition": "Quando os dados enviados forem classificados como Confidential.",
      "scope_link": {
        "question_quote": "antes de enviar dados a um fornecedor externo",
        "explanation": "As regras estabelecem autorização, finalidade, canal e restrição de acesso para esse envio externo."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-9b0d28fc0e3086af15def6c5a4d43fa93965cbbaa1b1a4ddf2803d4fb420ec35",
          "quote": "Confidential | Share only with an authorized recipient and approved business purpose. | Approved secure transfer or controlled platform; access limited to intended recipients."
        },
        {
          "unit_id": "DOC-005::unit-2fee2bb245a7ce31586728f0d21e26342a23219879b805fcea42718d7b2c8a88",
          "quote": "Confidential information shared externally must use an approved secure channel or controlled platform appropriate to the information classification. Corporate email alone does not convert an otherwise unapproved transfer into an approved secure transfer."
        }
      ]
    },
    {
      "need": "Para dados restritos, obter autorização explícita conforme o controle de segurança ou jurídico aplicável, utilizar mecanismo aprovado para dados restritos e documentar a autorização.",
      "use": "category",
      "condition": "Quando os dados enviados forem classificados como Restricted.",
      "scope_link": {
        "question_quote": "antes de enviar dados a um fornecedor externo",
        "explanation": "A regra define a autorização e o mecanismo necessários ao compartilhamento externo de dados restritos."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-9b0d28fc0e3086af15def6c5a4d43fa93965cbbaa1b1a4ddf2803d4fb420ec35",
          "quote": "Restricted | External sharing requires explicit authorization under the applicable security or legal control. | Approved restricted-data mechanism and documented authorization."
        }
      ]
    },
    {
      "need": "Limitar os dados enviados à transportadora às informações necessárias para executar o serviço logístico contratado.",
      "use": "category",
      "condition": "Quando o fornecedor externo destinatário for uma transportadora.",
      "scope_link": {
        "question_quote": "antes de enviar dados a um fornecedor externo",
        "explanation": "A regra limita o conteúdo que pode ser enviado a essa categoria de fornecedor externo."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-7c8625b003fc6835188e4cc28881508738aba9b952c95c306256f96faadc7b87",
          "quote": "Transportation carriers may receive only the information required to execute the contracted logistics service."
        }
      ]
    },
    {
      "need": "Não transmitir dados de clientes ou remessas classificados como confidenciais por e-mail comum desprotegido apenas porque o destinatário é uma transportadora contratada.",
      "use": "category",
      "condition": "Quando o fornecedor for uma transportadora contratada e os dados de clientes ou remessas forem classificados como confidenciais.",
      "scope_link": {
        "question_quote": "antes de enviar dados a um fornecedor externo",
        "explanation": "A regra impede considerar o contrato com a transportadora suficiente para permitir esse canal de envio."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-7c8625b003fc6835188e4cc28881508738aba9b952c95c306256f96faadc7b87",
          "quote": "Customer or shipment data classified as confidential must not be transmitted through ordinary unprotected email merely because the recipient is a contracted carrier."
        }
      ]
    },
    {
      "need": "Quando houver exceção, exigir justificativa de negócio documentada e as aprovações definidas pelos controles de segurança e de autoridade aplicáveis; um SOP operacional não pode criar, de forma independente, uma exceção à política corporativa.",
      "use": "category",
      "condition": "Quando houver exceção aos requisitos de compartilhamento externo.",
      "scope_link": {
        "question_quote": "antes de enviar dados a um fornecedor externo",
        "explanation": "A regra condiciona exceções aos requisitos desse envio, sem tornar aprovações de exceção uma exigência universal."
      },
      "supports": [
        {
          "unit_id": "DOC-005::unit-3e2cd1d6aa0b17f415f5cfb78e0895519691a34eabb2fd7e1907e495aef661fa",
          "quote": "Exceptions require documented business justification and the approvals defined by the applicable security and authority controls. An operational SOP cannot independently create an exception to a corporate policy."
        }
      ]
    }
  ],
  "action": {
    "kind": "complete"
  }
}

